const products = $input.all().map(i => i.json);
const brand = ($('Start (called by WF_01)').first().json.brandName || '').trim().toLowerCase();
const catalogSize = products.length;
if (catalogSize === 0) return [{ json: { classification: 'UNKNOWN', confidence: 0, evidence: { catalogSize: 0 } } }];

const brandLabelMatches = products.filter(p => (p.brandLabel||'').trim().toLowerCase() === brand).length;
const brandConsistency = brandLabelMatches / catalogSize >= 0.8;
const avgSellerCount = products.reduce((s,p)=>s+(p.sellerCount??1),0) / catalogSize;
const singleSellerDominant = avgSellerCount <= 1.3;
const sellerNameMatches = products.filter(p => (p.sellerName||'').trim().toLowerCase().includes(brand)).length;
const brandNameMatchesSellerName = sellerNameMatches / catalogSize >= 0.5;
const repeatedBrandedProducts = catalogSize >= 3 && brandConsistency;
const evidence = { brandConsistency, singleSellerDominant, sellerCountAcrossCatalog: Math.round(avgSellerCount*100)/100, catalogSize, brandNameMatchesSellerName, repeatedBrandedProducts };
const positiveSignals = [brandConsistency, singleSellerDominant, brandNameMatchesSellerName, repeatedBrandedProducts].filter(Boolean).length;

let classification, confidence;
if (!singleSellerDominant && avgSellerCount >= 3) { classification='LIKELY_RESELLER'; confidence=0.75; }
else if (!singleSellerDominant && avgSellerCount >= 2) { classification='WHOLESALE'; confidence=0.55; }
else if (positiveSignals >= 3) { classification='LIKELY_PRIVATE_LABEL'; confidence=0.85; }
else if (positiveSignals === 2) { classification='POSSIBLE_PRIVATE_LABEL'; confidence=0.6; }
else { classification='UNKNOWN'; confidence=0.3; }

return [{ json: { classification, confidence, evidence } }];
